CREATE TABLE public.faqs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), question text NOT NULL, answer text NOT NULL, keywords text[] NOT NULL DEFAULT '{}', category text NOT NULL DEFAULT '', priority int NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, search tsvector GENERATED ALWAYS AS (to_tsvector('english', question || ' ' || coalesce(array_to_string(keywords, ' '), ''))) STORED);
CREATE INDEX faqs_search_idx ON public.faqs USING gin (search);
GRANT SELECT ON public.faqs TO anon, authenticated;
GRANT ALL ON public.faqs TO service_role;
ALTER TABLE public.faqs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public FAQs" ON public.faqs FOR SELECT TO anon,authenticated USING(true);
CREATE FUNCTION public.match_faqs(query_text text) RETURNS TABLE(answer text, rank real) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT f.answer, ts_rank(f.search, websearch_to_tsquery('english', query_text)) AS rank FROM public.faqs f WHERE f.active AND f.search @@ websearch_to_tsquery('english', query_text) ORDER BY rank DESC, f.priority DESC LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.match_faqs(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.match_faqs(text) TO anon, authenticated, service_role;
