INSERT INTO public.faqs (question, answer, keywords, category, priority) VALUES
('Which areas and locations do you cover?', 'We work across Delhi NCR — including Noida (Sector 150 and the Expressway belt), Gurugram (Golf Course Extension and Sohna Road), the Yamuna Expressway near the upcoming Jewar Airport, and East & South Delhi. Tell us your preferred area and we will shortlist options for you.', ARRAY['areas','locations','delhi','ncr','noida','gurugram','gurgaon','yamuna','expressway','east delhi','south delhi','where','coverage'], 'Locations', 7),
('What types of property do you deal in?', 'Oceans & Earth Realty handles three categories: Residential (apartments, villas and holiday homes), Commercial (retail shops and office suites), and Plots & Land (residential plots and farm land). Let us know which one fits your plan.', ARRAY['property types','residential','commercial','plots','land','apartment','villa','office','retail','farm'], 'Property types', 6),
('What are your price ranges?', 'Options span a wide range — plots from around ₹45 L, commercial units from around ₹65 L, and residential homes from about ₹1.85 Cr upwards, depending on location and configuration. Share your budget and we will match it to the right inventory.', ARRAY['price','pricing','budget','cost','range','how much','rate'], 'Pricing', 5),
('How do I book a site visit?', 'Happy to arrange one. Share your preferred date, time and the project you like, and we will set up a site visit. You can also reach Saaurabh directly on WhatsApp or phone +91 99993 08625 to confirm a slot.', ARRAY['site visit','book','visit','tour','appointment','schedule','viewing'], 'Visits', 8),
('Do you help with home loans and EMI?', 'Yes. We guide you to partner banks for home loans and help you understand EMI, eligibility and down-payment. You can also try the EMI calculator on our Tools page for a quick estimate before you apply.', ARRAY['home loan','loan','emi','finance','bank','mortgage','eligibility','down payment'], 'Finance', 5),
('Are the projects RERA registered?', 'Our new projects are RERA registered, and we share the registration details so you can verify them before you commit. Ask us for the RERA number of any specific project you are considering.', ARRAY['rera','registration','registered','legal','approval','verify','compliance'], 'Legal', 4),
('What is the difference between resale and new projects?', 'New Projects are fresh launches or under-construction homes bought from the developer, often with flexible payment plans. Resale properties are ready, previously owned units you can move into sooner. We list both — tell us which suits you and we will filter accordingly.', ARRAY['resale','new projects','difference','ready to move','under construction','secondary'], 'Buying', 4),
('How can I contact you and what are your office hours?', 'Reach Saaurabh Nischal on phone or WhatsApp at +91 99993 08625, or email saaurabh@oceansandearthrealty.com. Our office is at Shop No-9/10, Plot No-6 L/S, Community Centre, Karkardooma, East Delhi, Delhi - 110092, open Monday to Saturday, 10am to 7pm.', ARRAY['contact','phone','email','office','hours','address','whatsapp','reach','timing','location office'], 'Contact', 9),
('Can I download a brochure?', 'Yes. Open any project on the Properties page and use the brochure download there to get the full details, floor plans and pricing. If you cannot find a brochure, message us and we will email it to you.', ARRAY['brochure','download','pdf','details','floor plan','catalogue'], 'Resources', 3),
('How do I get started?', 'Getting started is simple: tell us your budget, preferred area and property type, and we will share a shortlist. From there we arrange site visits and guide you through booking, loans and paperwork. Message Saaurabh on WhatsApp or call +91 99993 08625 to begin.', ARRAY['get started','start','begin','how to','first step','guidance','help'], 'Getting started', 8);
